def solve(g):
    H=len(g); W=len(g[0])
    insts=comps(g)
    # sort by (topmost row, leftmost col) to settle collisions in scan order
    insts.sort(key=lambda t:(min(r for r,_ in t[1]), min(x for _,x in t[1])))
    O=[[0]*W for _ in range(H)]
    placed=set()
    for v,c in insts:
        rs=min(r for r,_ in c); bb=max(r for r,_ in c); cl=min(x for _,x in c); cw=max(x for _,x in c)-cl+1
        inner={(r,x) for r in range(rs+1,bb) for x in range(cl+1,cw)}-c
        h=bb-rs+1
        if inner: tr=0; dr=-rs
        else: tr=H-h; dr=H-1-bb
        placed_cells=set(c)
        ok=False
        k=0
        while k<=H:
            sh={(r+dr+k, x) for r,x in c}
            if all(0<=r<H for r,_ in sh) and not (sh & placed):
                placed|=sh; ok=True; break
            k+=1
        assert ok, f'unplaced {v}'
    return O
